insert into passives (name, description, passive_type, context) values
  ('Adaptability', 'Moves that are the same type as you deal +4 damage.', 'ability', 'combat'),
  ('Aerilate', 'Normal-type moves performed by you are treated as Flying-type moves.', 'ability', 'combat'),
  ('Aftermath', 'When knocked out by a melee attack, the attacker loses 1d20 HP.', 'ability', 'combat'),
  ('Analytic', 'When attacking a foe who has already acted this round, deal +4 damage.', 'ability', 'combat'),
  ('Anger Point', 'When hit by a critical hit, raise Attack +6 for 10 mins.', 'ability', 'combat'),
  ('Anger Shell', 'While you are below 20 HP, your attacks deal +4 damage.', 'ability', 'combat'),
  ('Armor Tail', 'You are immune to priority attacks that are used out of turn order during combat.', 'ability', 'combat'),
  ('Aroma Veil', 'You and your allies within 10ft of you are immune to the effects of the moves Heal Block, Taunt, Encore, and Disable and the passive Cursed Body.', 'ability', 'combat'),
  ('Battery', 'Allies within 15 ft of you have +1 Special Attack.', 'ability', 'combat'),
  ('Battle Armor', 'Critical hits are treated as normal hits against you.', 'ability', 'combat'),
  ('Berserk', 'While below half HP, you have +2 Special Attack.', 'ability', 'combat'),
  ('Big Pecks', 'Your Defense cannot be lowered by a foe’s effects.', 'ability', 'combat'),
  ('Blaze', 'When you are below 20 HP, your Fire type attacks deal +4 damage.', 'ability', 'combat'),
  ('Cheek Pouch', 'Whenever you consume a berry, you recover 10 HP in addition to any other effects.', 'ability', 'combat'),
  ('Chlorophyll', 'While in Sunny Weather, your Speed is +2.', 'ability', 'combat'),
  ('Clear Body', 'Your stats cannot be lowered by a foe’s effects.', 'ability', 'combat'),
  ('Cloud Nine', 'As a free action you may deplete one use of Defog and use Defog.', 'ability', 'combat'),
  ('Color Change', 'Whenever you are attacked, your type is changed to the same type as the attack after taking damage and effects for 5 mins.', 'ability', 'combat'),
  ('Comatose', 'You are always Asleep but can still act as if you aren’t. You are also immune to other afflictions.', 'ability', 'combat'),
  ('Commander', 'When adjacent to an allied Dondozo, Tatsugiri can go into Dondozo’s mouth as a free action. While inside the allied Dondozo’s mouth, Tatsugiri cannot act and its Skills and Passives cannot be used, but the allied Dondozo has +2 to its Attack, Defense, Special Attack, Special Defense, and Speed. Additionally, Tatsugiri cannot be targeted or hit by any attacks, is unaffected by the effects of any moves, and allows the allied Dondozo to use any of Tatsugiri’s moves.', 'ability', 'combat'),
  ('Competitive', 'If a foe lowers any of your stats, you have +2 Special Attack until your lowered stats are returned to normal.', 'ability', 'combat'),
  ('Compound Eyes', 'Add +1 during accuracy check whenever you use a ranged attack.', 'ability', 'combat'),
  ('Corrosion', 'You can Poison and Toxify Steel-types and Poisontypes.', 'ability', 'combat'),
  ('Costar', 'At the start of combat, copy a stat passive from your nearest ally until the end of combat.', 'ability', 'combat'),
  ('Cud Chew', 'When you consume a berry, its effect will activate a second time 1 round of combat later.', 'ability', 'combat'),
  ('Curious Medicine', 'Your stats and your adjacent ally’s stats cannot be lowered by a foe’s effects.', 'ability', 'combat'),
  ('Cursed Body', 'When you are hit by a foe’s melee attack, disable that attack for 10 mins. Cursed Body can only affect one attack at a time.', 'ability', 'combat'),
  ('Cute Charm', 'Whenever you are hit with a melee attack, roll 1d4. On 4, Infatuate the attacker.', 'ability', 'combat'),
  ('Damp', 'Chloroblast, Explosion, Misty Explosion, and Self- Destruct fail to do anything if used within 40ft of you.', 'ability', 'combat'),
  ('Dazzling', 'You may not be targeted by Priority moves that are being used out of turn order.', 'ability', 'combat'),
  ('Defeatist', 'When your HP is below half of your max hit points, your stats are all -2.', 'ability', 'combat'),
  ('Defiant', 'If a foe lowers any of your stats, you have +2 Attack until your lowered stats are returned to normal.', 'ability', 'combat'),
  ('Disguise', 'The first time you are hit with an attack each encounter, the attack is negated.', 'ability', 'combat'),
  ('Download', 'Your Attack is +1 against targets with lower Defense than Special Defense. Your Special Attack is +1 against targets with lower Special Defense than Defense.', 'ability', 'combat'),
  ('Drizzle', 'As a free action you may deplete one use of Rain Dance and use Rain Dance.', 'ability', 'combat'),
  ('Drought', 'As a free action you may deplete one use of Sunny Day and use Sunny Day.', 'ability', 'combat'),
  ('Dry Skin', 'In sunny weather, you lose 4 HP at the end of your actions. In rainy weather, you recover 4 HP at the end of your actions. You are immune to Water-type attacks.', 'ability', 'combat'),
  ('Early Bird', 'You roll twice during checks to wake from Sleep and use the higher result.', 'ability', 'combat'),
  ('Earth Eater', 'When you are hit by a Ground-type attack, halve the damage, then you heal that much HP instead of taking damage.', 'ability', 'combat'),
  ('Effect Spore', 'Whenever you are hit with a melee attack, roll 1d4. On 4, randomly either Paralyze, Poison, or put to Sleep the attacker.', 'ability', 'combat'),
  ('Electric Surge', 'As a free action you may deplete one use of Electric Terrain and use Electric Terrain.', 'ability', 'combat'),
  ('Electromorphosis', 'When hit by an attack that deals damage, you may use the move Charge as a free action', 'ability', 'combat'),
  ('Emergency Exit', 'You cannot fight when first damaged below half of Max HP. You will want to run away or return to a Poke Ball for 2 rounds. During those two rounds, your speed is doubled.', 'ability', 'combat'),
